      "قَاعِدَةُ (٧٢) الذِّهْنِيَّةُ السَّرِيعَةُ لِحِسَابِ زَمَنِ تَضَاعُفِ أَيِّ اسْتِثْمَارٍ أَوْ تَعْدَادٍ سُكَّانِيٍّ"
