      "stem": "آلَةُ طِبَاعَةٍ ثَمَنُهَا ٢٬٤٠٠ دِينَارٍ، وَعُمْرُهَا الإِنْتَاجِيُّ ٤ سَنَوَاتٍ، وَقِيمَتُهَا المُتَبَقِّيَةُ بَعْدَ ذٰلِكَ ٤٠٠ دِينَارٍ؛ مَا مِقْدَارُ إِهْلَاكِهَا السَّنَوِيِّ الثَّابِتِ؟",
