      "stem": "وَقَفَ رَاصِدٌ عَلَى بُعْدِ ٢٠ مِتْرًا مِنْ قَاعِدَةِ سَارِيَةٍ، فَكَانَتْ زَاوِيَةُ ارْتِفَاعِ قِمَّتِهَا مِنْ مُسْتَوَى الأَرْضِ ٤٥ دَرَجَةً؛ كَمْ يَبْلُغُ ارْتِفَاعُ السَّارِيَةِ؟",
