    "essence": "فِي الهَنْدَسَةِ التَّحْلِيلِيَّةِ نَحْكُمُ عَلَى تَوَازِي شَارِعَيْنِ أَوْ تَعَامُدِهِمَا عَلَى الخَرِيطَةِ بِمُجَرَّدِ فَحْصِ مَيْلَيْهِمَا دُونَ حَاجَةٍ لِلْمِنْقَلَةِ: فَإِذَا تَسَاوَى المَيْلَانِ (م١ = م٢) سَارَ الخَطَّانِ مُتَوَازِيَيْنِ كَسِكَّتَيِ القِطَارِ، وَإِذَا كَانَ أَحَدُهُمَا مَقْلُوبَ الآخَرِ بِإِشَارَةٍ مُخَالِفَةٍ بِحَيْثُ يَكُونُ م١ × م٢ = -١، تَقَاطَعَا بِزَاوِيَةٍ قَائِمَةٍ تَامَّةٍ (٩٠°).\n\nيُفِيدُ شَرْطُ التَّعَامُدِ فِي إِيجَادِ أَقْصَرِ وَصْلَةٍ مُمْكِنَةٍ؛ فَإِذَا أَرَدْتَ مَدَّ أُنْبُوبِ مَاءٍ مِنْ بَيْتٍ إِلَى خَطِّ الأَنَابِيبِ الرَّئِيسِيِّ بِأَقَلِّ تَكْلِفَةٍ وَأَقْصَرِ طُولٍ، وَجَبَ أَنْ يَسِيرَ الأُنْبُوبُ الفَرْعِيُّ عَمُودِيًّا تَمَامًا عَلَى الخَطِّ الرَّئِيسِيِّ.",
    "tutorContext": "التَّوَازِي: م_1 = م_2 (مَعَ اخْتِلَاف المَقْطَع الصَّادِيّ لِئَلَّا يَنْطَبِقَا). التَّعَامُد: م_1 × م_2 = -1 أَيّ م_2 = -1 / م_1 (بِاسْتِثْنَاءِ الأُفُقِيّ م=0 مَعَ الرَّأْسِيّ غَيْرَ المعرفِ فَهُمَا مُتَعَامِدَان أَيْضًا). أَقْصَر بَعْد بَيْنَ نُقْطَةِ وَمُسْتَقِيم هُوَ العَمُود النَّازِل مِنْهَا عَلَيْهِ.",
