          "text": "٢٥ مِلِّيغْرَامًا لِأَنَّ ٩ سَاعَاتٍ تَضُمُّ ٣ فَتَرَاتِ تَنْصِيفٍ مُتَتَالِيَةٍ (٢٠٠ ← ١٠٠ ← ٥٠ ← ٢٥).",
