      "المَدَى الرُّبَيْعِيُّ (ر٣ - ر١) الَّذِي يَحْتَضِنُ النِّصْفَ الأَوْسَطَ (٥٠٪) مِنَ المُجْتَمَعِ",
      "قِرَاءَةُ مُخَطَّطَاتِ النُّمُوِّ المِئِينِيَّةِ فِي الطِّبِّ وَتَقَارِيرِ الِاخْتِبَارَاتِ المِعْيَارِيَّةِ"
