    "essence": "لَا يَكْفِي رَقْمٌ وَاحِدٌ لِوَصْفِ مَجْمُوعَةٍ كَبِيرَةٍ مِنَ البَيَانَاتِ؛ لِذٰلِكَ يَرْسُمُ الإِحْصَائِيُّونَ «المُخَطَّطَ الصُّنْدُوقِيَّ» الَّذِي يُلَخِّصُ البَيَانَاتِ فِي خَمْسِ عَلَامَاتٍ: الحَدِّ الأَدْنَى، وَالرُّبَيْعِ الأَوَّلِ (ر١ عِنْدَ ٢٥٪)، وَالوَسِيطِ (ر٢ عِنْدَ ٥٠٪)، وَالرُّبَيْعِ الثَّالِثِ (ر٣ عِنْدَ ٧٥٪)، وَالحَدِّ الأَعْلَى.\n\nيَقِيسُ طُولُ الصُّنْدُوقِ الأَوْسَطِ (المَدَى الرُّبَيْعِيُّ = ر٣ - ر١) مَدَى تَقَارُبِ النِّصْفِ الأَوْسَطِ مِنَ النَّاسِ بَعِيدًا عَنِ الأَطْرَافِ الشَّاذَّةِ. وَبِهٰذِهِ اللُّغَةِ نَفْسِهَا يَقْرَأُ طَبِيبُ الأَطْفَالِ مُنْحَنَيَاتِ الطُّولِ وَالوَزْنِ؛ فَطِفْلٌ يَقَعُ عِنْدَ المِئِينِ ٧٥ يَعْنِي أَنَّ طُولَهُ يَفُوقُ ٧٥٪ مِنْ أَقْرَانِهِ فِي العُمْرِ نَفْسِهِ.",
    "tutorContext": "الخَمْسَة أَرْقَام المُلَخِّصَة: (الأَدْنَى، ر1، الوَسِيط ر2، ر3، الأَعْلَى). المَدَى الرُّبَيْعِيّ IQR = ر3 - ر1 وَيَضُمّ 50% مِنَ البَيَانَاتِ الوُسْطَى. أَيّ قِيمَة تَبْتَعِد أَكْثَر مِنْ 1.5 × IQR عَنْ الصُّنْدُوقِ تُعَدّ قِيمَة مُتَطَرِّفَة إِحْصَائِيًّا.",
    "apply": "رَتِّبْ دَرَجَاتِ سَبْعَةِ طُلَّابٍ تَصَاعُدِيًّا: (٦٠، ٦٨، ٧٢، ٧٥، ٨٠، ٨٨، ٩٥)، ثُمَّ اسْتَخْرِجْ بِيَدِكَ الوَسِيطَ (ر٢)، وَالرُّبَيْعَ الأَوَّلَ (ر١)، وَالرُّبَيْعَ الثَّالِثَ (ر٣)، وَاحْسُبِ المَدَى الرُّبَيْعِيَّ.",
