      "stem": "مَا أَقْصَى عَدَدٍ مِنَ الخُطُوَاتِ يَحْتَاجُهُ البَحْثُ الثُّنَائِيُّ لِلْعُثُورِ عَلَى كَلِمَةٍ دَاخِلَ قَائِمَةٍ مُرَتَّبَةٍ تَضُمُّ ٦٤ كَلِمَةً؟",
