      "تَنَاسُبُ طُولِ كُلِّ ضِلْعٍ مَعَ جَيْبِ الزَّاوِيَةِ المُقَابِلَةِ لَهُ: أ ÷ جا(أ) = ب ÷ جا(ب)",
