      "قَانُونُ كِبْلَرَ الأَوَّلُ: الكَوَاكِبُ تَدُورُ فِي مَدَارَاتٍ إِهْلِيلَجِيَّةٍ تَقَعُ الشَّمْسُ فِي إِحْدَى بُؤْرَتَيْهَا",
