      "stem": "كَيْفَ يَسْتَفِيدُ جِهَازُ تَفْتِيتِ حَصَيَاتِ الكُلَى بِالمَوْجَاتِ الصَّوْتِيَّةِ مِنْ هَنْدَسَةِ القَطْعِ النَّاقِصِ؟",
