      "التَّدَاخُلُ البَنَّاءُ (قِمَّةٌ مَعَ قِمَّةٍ يُضَاعِفُ الشِّدَّةَ) وَالتَّدَاخُلُ الهَدَّامُ (قِمَّةٌ مَعَ قَاعٍ يُفْنِي الصَّوْتَ)",
