    "essence": "تُعَدُّ «مُبَرْهَنَةُ بَايْزَ» دُرَّةَ التَّفْكِيرِ العِلْمِيِّ وَالطِّبِّيِّ: لِنَفْرِضْ أَنَّ مَرَضًا نَادِرًا يُصِيبُ شَخْصًا وَاحِدًا مِنْ كُلِّ ١٬٠٠٠ شَخْصٍ، وَأُجْرِيَ فَحْصٌ دِقَّتُهُ ٩٩٪ (أَيْ يُخْطِئُ بِنِسْبَةِ ١٪ فَقَطْ). إِذَا فَحَصْنَا ١٬٠٠٠ شَخْصٍ عَشْوَائِيًّا، فَسَيَظْهَرُ المَرِيضُ الحَقِيقِيُّ الوَاحِدُ إِيجَابِيًّا، لٰكِنَّ ١٪ مِنَ الأَصِحَّاءِ الِ ٩٩٩ (أَيْ نَحْوَ ١٠ أَصِحَّاءَ!) سَتَظْهَرُ نَتِيجَتُهُمْ إِيجَابِيَّةً كَاذِبَةً أَيْضًا!\n\nإِذَنْ مِنْ بَيْنِ ١١ شَخْصًا ظَهَرَ فَحْصُهُمْ إِيجَابِيًّا، يُوجَدُ مَرِيضٌ حَقِيقِيٌّ وَاحِدٌ فَقَطْ (نَحْوُ ٩٪ لَا ٩٩٪!). لِذٰلِكَ لَا يَحْكُمُ الطَّبِيبُ الحَاذِقُ مِنْ فَحْصٍ مَسْحِيٍّ مُنْفَرِدٍ دُونَ النَّظَرِ إِلَى الأَعْرَاضِ السَّرِيرِيَّةِ وَإِجْرَاءِ فَحْصٍ تَأْكِيدِيٍّ ثَانٍ يَرْفَعُ اليَقِينَ فَوْقَ ٩٩٪.",
    "tutorContext": "قَانُون بَايْز بِالعَدِّ الطَّبِيعِيّ (أَسْهَل لِلفَهْمِ العَامّ): نَقْسِم المُجْتَمَع إِلَى مُصَابِين وَأَصِحَّاء، ثُمَّ نَحْسُب الإِيجَابِيَّاتِ الحَقِيقِيَّةُ وَالإِيجَابِيَّاتِ الكَاذِبَة، فَيَكُون احْتِمَال الإِصَابَة عِنْدَ إِيجَابِيَّةِ الفَحْص = الإِيجَابِيَّاتِ الحَقِيقِيَّةُ ÷ إِجْمَالِيّ الإِيجَابِيَّاتِ.",
