      "stem": "فِي مِثَالِ ١٬٠٠٠ شَخْصٍ فِيهِمْ مَرِيضٌ وَاحِدٌ حَقِيقِيٌّ ظَهَرَ إِيجَابِيًّا و٩ أَصِحَّاءَ ظَهَرُوا إِيجَابِيِّينَ بِالخَطَأِ (إِجْمَالِيُّ الإِيجَابِيِّينَ ١٠)، مَا احْتِمَالُ أَنْ يَكُونَ صَاحِبُ النَّتِيجَةِ الإِيجَابِيَّةِ مَرِيضًا فِعْلًا؟",
