      "stem": "مَاذَا يَنْتُجُ عِنْدَ ضَرْبِ أَيِّ مَصْفُوفَةٍ مُرَبَّعَةٍ قَابِلَةٍ لِلْعَكْسِ (أ) فِي نَظِيرِهَا الضَّرْبِيِّ (أ⁻¹)؟",
