      "حِسَابُ القِسْطِ الشَّهْرِيِّ المُتَسَاوِي: (السِّعْرُ الإِجْمَالِيُّ - الدُّفْعَةُ المُقَدَّمَةُ) ÷ عَدَدِ الأَشْهُرِ",
