    "essence": "يَنْظُرُ النَّاسُ عَادَةً إِلَى التَّكْلِفَةِ المَكْتُوبَةِ فِي الفَاتُورَةِ وَيَغْفُلُونَ عَنْ «تَكْلِفَةِ الفُرْصَةِ البَدِيلَةِ»: وَهِيَ قِيمَةُ أَفْضَلِ خِيَارٍ مُتَاحٍ ضَحَّيْتَ بِهِ حِينَ اخْتَرْتَ خِيَارَكَ الحَالِيَّ! فَمَنْ يَمْلِكُ دُكَّانًا يُمْكِنُ تَأْجِيرُهُ لِغَيْرِهِ ب ٥٠٠ دِينَارٍ شَهْرِيًّا، فَفَتَحَ فِيهِ مَشْرُوعًا يَدِرُّ عَلَيْهِ ٤٠٠ دِينَارٍ قَائِلًا «أَنَا لَا أَدْفَعُ إِيجَارًا»، هُوَ فِي الحَقِيقَةِ يَخْسَرُ اقْتِصَادِيًّا ١٠٠ دِينَارٍ شَهْرِيًّا مُقَارَنَةً بِأَفْضَلِ بَدِيلٍ مُتَاحٍ!\n\nوَيَتَجَلَّى هٰذَا المِيزَانُ بِأَبْلَغِ صُوَرِهِ فِي الوَقْتِ: فَسَاعَتَانِ تَقْضِيهِمَا فِي تَصَفُّحٍ عَبَثِيٍّ تَبْدُوَانِ «مَجَّانِيَّتَيْنِ» بِالنُّقُودِ، لٰكِنَّ تَكْلِفَتَهُمَا الحَقِيقِيَّةَ هِيَ المَهَارَةُ أَوِ المَسْأَلَةُ أَوْ صِلَةُ الرَّحِمِ الَّتِي كَانَ يُمْكِنُ إِتْمَامُهَا فِي تِلْكَ السَّاعَتَيْنِ.",
    "tutorContext": "الرِّبْح المُحَاسَبِيّ = الإِيرَاد - التَّكَالِيف الصَّرِيحَة فَقَطْ. الرِّبْح الِاقْتِصَادِيّ = الإِيرَاد - (التَّكَالِيف الصَّرِيحَة + تَكْلِفَة الفُرْصَة البَدِيلَة لِأَفْضَلِ بَدِيل وَاحِد فَقَطْ وَلَيْسَ مَجْمُوع كُلّ البَدَائِل).",
    "apply": "أَمَامَكَ يَوْمُ عُطْلَةٍ فِيهِ ثَلَاثَةُ خِيَارَاتٍ لِعَمَلٍ جُزْئِيٍّ مَشْرُوعٍ: الأَوَّلُ يُعْطِي ٣٠ دِينَارًا، وَالثَّانِي ٢٥ دِينَارًا، وَالثَّالِثُ ٢٠ دِينَارًا (وَلَا يُمْكِنُ الجَمْعُ بَيْنَهَا)؛ حَدِّدْ مَا هِيَ تَكْلِفَةُ الفُرْصَةِ البَدِيلَةِ إِذَا اخْتَرْتَ الخِيَارَ الأَوَّلَ.",
