      "stem": "مَا الشَّكْلُ الهَنْدَسِيُّ النَّاتِجُ عَنْ قَطْعِ أُسْطُوَانَةٍ قَائِمَةٍ بِمُسْتَوًى عَمُودِيٍّ يَمُرُّ بِمِحْوَرِهَا مِنْ أَعْلَاهَا إِلَى قَاعِدَتِهَا؟",
