      "stem": "كَمْ يَكُونُ مَجْمُوعُ زَوَايَا المُثَلَّثِ الكُرَوِيِّ المَرْسُومِ مِنْ أَقْوَاسِ دَوَائِرَ عُظْمَى عَلَى سَطْحِ الكُرَةِ الأَرْضِيَّةِ؟",
