      "وَفْرُ الوَقُودِ وَالوَقْتِ فِي تَخْطِيطِ مَسَارَاتِ سَيَّارَاتِ البَلَدِيَّةِ وَفَحْصِ أَنَابِيبِ المِيَاهِ"
