    "essence": "فِي مَدِينَةِ كُونِيغْسْبِيرْغَ كَانَ هُنَاكَ ٧ جُسُورٍ تَرْبِطُ بَيْنَ ٤ مَنَاطِقَ، فَتَسَاءَلَ الأَهَالِي: هَلْ يَسْتَطِيعُ مُتَنَزِّهٌ عُبُورَ الجُسُورِ السَّبْعَةِ كُلِّهَا مَرَّةً وَاحِدَةً دُونَ تَكْرَارِ أَيِّ جِسْرٍ؟ حَلَّ أُويْلَرُ اللُّغْزَ بِقَاعِدَةٍ خَالِدَةٍ: كُلُّ مَنْطِقَةٍ تَدْخُلُهَا فِي وَسَطِ الرِّحْلَةِ لَا بُدَّ أَنْ تَخْرُجَ مِنْهَا، فَيَلْزَمُهَا عَدَدٌ زَوْجِيٌّ مِنَ الجُسُورِ! وَلَا يُسْمَحُ بِالدَّرَجَةِ الفَرْدِيَّةِ إِلَّا لِنُقْطَةِ الِانْطِلَاقِ وَنُقْطَةِ التَّوَقُّفِ فَقَطْ (أَيْ ٠ أَوْ ٢ مِنْ الرُّؤُوسِ الفَرْدِيَّةِ فَحَسْبُ)!\n\nلَمْ يَكُنْ هٰذَا مُجَرَّدَ تَسْلِيَةٍ؛ فَعَلَيْهِ تَعْتَمِدُ البَلَدِيَّاتُ وَشَرِكَاتُ التَّوْزِيعِ اليَوْمَ لِرَسْمِ خُطُوطِ شَاحِنَاتِ النَّظَافَةِ وَكَنَّاسَاتِ الثُّلُوجِ وَقَارِئِي العَدَّادَاتِ حَتَّى تَمْسَحَ كُلَّ شَارِعٍ مَرَّةً وَاحِدَةً دُونَ دَوَرَانٍ ضَائِعٍ.",
    "tutorContext": "الدّارة الأُويْلَرِيَّة (تَبْدَأ وَتَنْتَهِي فِي نَفْس النُّقْطَة وتمرّ بِكُلّ حَافَّة مَرَّة وَاحِدَة): تَشْتَرِطُ أَنْ تَكُونَ الشَّبَكَة مُتَّصِلَة وَجَمِيع رُؤُوسُهَا زَوْجِيَّة الدَّرَجَة (0 فَرْدِيّ). المَسَار الأُويْلَرِيّ المَفْتُوح: يُشْتَرَط وُجُود رَأْسَيْن فَرْدِيَّيْن بِالضَّبْطِ (أَحَدُهُمَا بِدَايَة وَالآخَر نِهَايَة).",
