      "stem": "لِرَبْطِ ١٠ قُرًى بِشَبَكَةِ مِيَاهٍ وَاحِدَةٍ مُتَّصِلَةٍ عَلَى شَكْلِ شَجَرَةٍ مُمْتَدَّةٍ بِلَا حَلَقَاتٍ زَائِدَةٍ، مَا أَقَلُّ عَدَدٍ لَازِمٍ مِنْ خُطُوطِ الأَنَابِيبِ بَيْنَهَا؟",
