          "text": "أَنَّ حَرَارَةَ المَاءِ مَرَّتْ حَتْمًا بِكُلِّ دَرَجَةٍ بَيْنَ ٢٠° و ٩٠° (مِثْلَ ٥٠° تَمَامًا) فِي لَحْظَةٍ زَمَنِيَّةٍ مَا.",
