    "essence": "إِذَا نَمَا كَائِنٌ حَيٌّ بِنِسْبَةِ ١٠٠٪ مَرَّةً وَاحِدَةً فِي نِهَايَةِ الفَتْرَةِ تَضَاعَفَ إِلَى ٢، فَمَاذَا لَوْ تَوَزَّعَ هٰذَا النُّمُوُّ لِيَحْدُثَ تَرَاكُمِيًّا كُلَّ شَهْرٍ، أَوْ كُلَّ يَوْمٍ، أَوْ كُلَّ ثَانِيَةٍ بِلَا تَوَقُّفٍ كَمَا تَنْمُو الأَنْسِجَةُ الطَّبِيعِيَّةُ؟ لَنْ يَنْفَجِرَ النَّاتِجُ إِلَى مَا لَا نِهَايَةَ، بَلْ تَقْتَرِبُ العِبَارَةُ (١ + ١÷ن)^ن مِنْ ثَابِتٍ طَبِيعِيٍّ مُدْهِشٍ يُرْمَزُ لَهُ بِالحَرْفِ (ه أَوْ e) وَقِيمَتُهُ التَّقْرِيبِيَّةُ ٢٫٧١٨!\n\nيُسَمَّى اللُّوغَارِيتْمُ لِهٰذَا الأَسَاسِ «اللُّوغَارِيتْمَ الطَّبِيعِيَّ (لِط أَوْ ln)»؛ لِأَنَّ الدَّالَّةَ ه^س تَنْفَرِدُ فِي الرِّيَاضِيَّاتِ كُلِّهَا بِأَنَّ مُشْتَقَّتَهَا (سُرْعَةَ تَغَيُّرِهَا فِي كُلِّ لَحْظَةٍ) هِيَ ه^س نَفْسُهَا دُونَ أَيِّ مُعَامِلٍ إِضَافِيٍّ!",
    "tutorContext": "العَدَد e = lim (n→∞) (1 + 1/n)^n ≈ 2.71828 (عَدَد غَيْرَ نِسْبِيّ مُتَسَام مِثْلَ π). مُشْتَقَّة e^x هِيَ e^x، وَاللُّوغَارِيتْم الطَّبِيعِيّ ln(x) هُوَ عَكْسَهَا حَيْثُ ln(e) = 1 و ln(1) = 0.",
    "apply": "احْسُبْ قِيمَةَ العِبَارَةِ (١ + ١÷ن)^ن لِلْقِيَمِ الصَّغِيرَةِ ن = ١، ثُمَّ ن = ٢، ثُمَّ ن = ٤، وَلَاحِظْ كَيْفَ تَصْعَدُ القِيَمُ (٢ ← ٢٫٢٥ ← ٢٫٤٤...) مُقْتَرِبَةً بِهُدُوءٍ مِنْ سَقْفِ ٢٫٧١٨ دُونَ أَنْ تَبْلُغَ العَدَدَ ٣ أَبَدًا!",
