    "essence": "تَخَيَّلْ مُنْقِذًا عَلَى شَاطِئٍ رَمْلِيٍّ رَأَى غَرِيقًا فِي البَحْرِ بِزَاوِيَةٍ مَائِلَةٍ؛ إِنَّهُ يَرْكُضُ عَلَى الرَّمْلِ أَسْرَعَ بِثَلَاثِ مَرَّاتٍ مِنْ سِبَاحَتِهِ فِي المَاءِ! لَوْ تَحَرَّكَ فِي خَطٍّ مُسْتَقِيمٍ مُبَاشِرٍ قَضَى وَقْتًا طَوِيلًا فِي السِّبَاحَةِ البَطِيئَةِ، أَمَّا إِذَا جَرَى مَسَافَةً أَطْوَلَ قَلِيلًا عَلَى الرَّمْلِ السَّرِيعِ ثُمَّ انْكَسَرَ مَسَارُهُ لِيَقْطَعَ مَسَافَةً أَقْصَرَ فِي المَاءِ، وَصَلَ إِلَى الغَرِيقِ فِي «أَقَلِّ زَمَنٍ مُمْكِنٍ»!\n\nالمُعْجِزُ أَنَّ شُعَاعَ الضَّوْءِ يَفْعَلُ ذٰلِكَ تَمَامًا حِينَ يَنْتَقِلُ مِنَ الهَوَاءِ السَّرِيعِ إِلَى الزُّجَاجِ أَوِ المَاءِ الأَبْطَأِ فَيَنْكَسِرُ وَفْقَ القَانُونِ الَّذِي اكْتَشَفَهُ أَبُو سَعْدٍ العَلَاءُ بْنُ سَهْلٍ لِتصْمِيمِ العَدَسَاتِ: نِسْبَةُ جَيْبَيْ زَاوِيَتَيِ السُّقُوطِ وَالِانْكِسَارِ تُسَاوِي نِسْبَةَ سُرْعَتَيِ الضَّوْءِ فِي الوَسَطَيْنِ!",
    "tutorContext": "قَانُون ابْن سَهْل / سَنَيَل: جا(ه_1) / ع_1 = جا(ه_2) / ع_2، وَيَشْتَقُ مُبَاشَرَة مِنْ جَعَل مُشْتَقَّة الزَّمَن الكُلِّيّ ز = ف_1/ع_1 + ف_2/ع_2 تُسَاوِي صِفْرًا (مَبْدَأ فِيرْمَا لِلزَّمَنِ الأَقَلّ).",
    "apply": "ضَعْ قَلَمًا مَائِلًا فِي كُوبِ مَاءٍ شَفَّافٍ وَانْظُرْ إِلَى انْكِسَارِهِ الظَّاهِرِيِّ عِنْدَ سَطْحِ المَاءِ، ثُمَّ اشْرَحْ لِأَهْلِ بَيْتِكَ التَّشْبِيهَ البَدِيعَ بَيْنَ انْكِسَارِ الضَّوْءِ وَمَسَارِ المُنْقِذِ الذَّكِيِّ عَلَى الشَّاطِئِ.",
