    "essence": "كَيْفَ نَحْسُبُ مِسَاحَةَ شَكْلٍ مُنْحَنٍ كَالدَّائِرَةِ وَنَحْنُ لَا نَعْرِفُ إِلَّا حِسَابَ مِسَاحَةِ المُثَلَّثَاتِ ذَاتِ الأَضْلَاعِ المُسْتَقِيمَةِ؟ ابْتَكَرَ أُودُوكْسُوسُ وَأَرْخَمِيدِسُ «طَرِيقَةَ الِاسْتِنْفَادِ»: نَرْسُمُ سُدَاسِيًّا مُنْتَظَمًا دَاخِلَ الدَّائِرَةِ وَسُدَاسِيًّا خَارِجَهَا، فَتَنْحَصِرُ مِسَاحَةُ الدَّائِرَةِ بَيْنَهُمَا؛ ثُمَّ نُضَاعِفُ الأَضْلَاعَ إِلَى ١٢ ثُمَّ ٢٤ ثُمَّ ٤٨ ضِلْعًا فَتَسْتَنْفِدُ المُضَلَّعَاتُ الفَرَاغَ حَتَّى تَنْطَبِقَ عَلَى الدَّائِرَةِ!\n\nوَفِي سَمَرْقَنْدَ بَلَغَ غِيَاثُ الدِّينِ الكَاشِيُّ ذُرْوَةً لَمْ يُسْبَقْ إِلَيْهَا لِقُرُونٍ طَوِيلَةٍ؛ إِذْ حَسَبَ مُحِيطَ مُضَلَّعٍ يَضُمُّ ٣ × ٢²⁸ ضِلْعًا (أَكْثَرَ مِنْ ٨٠٠ مِلْيُونِ ضِلْعٍ!) فَأَخْرَجَ قِيمَةَ (π) صَحِيحَةً إِلَى ١٦ مَرْتَبَةً عَشْرِيَّةً!",
    "tutorContext": "مُحِيط السُّدَاسِيّ المُنْتَظِم المُحَاط بِدَائِرَة قُطْرِهَا 1 يُسَاوِي 3 تَمَامًا (لِأَنّ ضِلْعِهِ = نق = 0.5)، وَمُحِيط المُرَبَّع المُحِيط بِهَا يُسَاوِي 4؛ وَمِنْ هُنَا الحَصَر البَدِيهِيّ الأَوَّل: 3 < π < 4، وَبِمُضَاعَفَة الأَضْلَاع يَضِيق الحَصَر بِدِقَّة غَيْرَ مَحْدُودَةِ.",
    "apply": "ارْسُمْ دَائِرَةً نِصْفُ قُطْرِهَا ١ سُمّ (قُطْرُهَا ٢ سُمّ)، وَأَحِطْهَا بِمُرَبَّعٍ خَارِجِيٍّ ضِلْعُهُ ٢ سُمّ، وَارْسُمْ دَاخِلَهَا سُدَاسِيًّا مُنْتَظَمًا ضِلْعُهُ ١ سُمّ؛ احْسُبْ نِصْفَ مُحِيطِ كُلٍّ مِنْهُمَا لِتُبَرْهِنَ بِيَدِكَ أَنَّ ٣ < π < ٤!",
