      "stem": "مَا الإِحْدَاثِيُّ السِّينِيُّ لِمَرْكَزِ ثِقَلِ صَفِيحَةٍ مُثَلَّثَةٍ مُنْتَظِمَةِ السُّمْكِ رُؤُوسُهَا (٠، ٠) و(٦، ٠) و(٣، ٩)؟",
