      "قِصَّةُ إِبْرَاهَامَ وَالْد الشَّهِيرَةِ: لِمَاذَا دَرَّعَ المَنَاطِقَ السَّلِيمَةَ فِي الطَّائِرَاتِ العَائِدَةِ بَدَلَ المَثْقُوبَةِ؟",
