      "تَبْسِيطُ دَوَرَانِ الأَجْسَامِ فِي الرُّسُومِ الحَاسُوبِيَّةِ وَالطَّيَرَانِ بِضَرْبِ الأَعْدَادِ المُرَكَّبَةِ"
