    "essence": "يَزُولُ كُلُّ غُمُوضٍ عَنِ العَدَدِ التَّخَيُّلِيِّ (ت) حِينَ نَرَاهُ هَنْدَسِيًّا! عَلَى خَطِّ الأَعْدَادِ، ضَرْبُ أَيِّ مُتَّجِهٍ فِي (-١) يَعْكِسُ اتِّجَاهَهُ إِلَى الجِهَةِ المُقَابِلَةِ تَمَامًا أَيْ يُدِيرُهُ ١٨٠ دَرَجَةً. فَإِذَا أَرَدْنَا عَمَلِيَّةً إِذَا كَرَّرْنَاهَا مَرَّتَيْنِ أَعْطَتْ دَوَرَانًا ب ١٨٠°، فَلَا بُدَّ أَنْ تَكُونَ المَرَّةُ الوَاحِدَةُ مِنْهَا «دَوَرَانًا بِزَاوِيَةِ ٩٠ دَرَجَةً»! وَهٰذَا هُوَ الضَّرْبُ فِي (ت) بِعَيْنِهِ!\n\nفَإِذَا بَدَأْتَ بِالعَدَدِ ١ شَرْقًا وَضَرَبْتَهُ فِي (ت) دَارَ ٩٠° لِيُشِيرَ شَمَالًا (ت)، فَإِذَا ضَرَبْتَهُ فِي (ت) ثَانِيَةً دَارَ ٩٠° أُخْرَى لِيُشِيرَ غَرْبًا (-١)، وَفِي الثَّالِثَةِ جَنُوبًا (-ت)، وَفِي الرَّابِعَةِ يَعُودُ شَرْقًا (+١)! لِذٰلِكَ تُدِيرُ مُحَرِّكَاتُ الرُّسُومِ الأَشْكَالَ بِخُطْوَةِ ضَرْبٍ مُرَكَّبَةٍ وَاحِدَةٍ.",
    "tutorContext": "مِقْيَاس (طُول) العَدَد المُرَكَّب ع = أ + ب ت هُوَ |ع| = √(أ² + ب²). عِنْدَ ضَرْب عَدَدَيْن مركّبين تَضْرِب أَطْوَالهُمَا وَتَجْمَع زَوَايَاهُمَا! الضَّرْب فِي i يَنْقُلُ النُّقْطَة (س، ص) إِلَى (-ص، س) أَيّ دَوَرَان 90° عَكْس عَقَارِب السَّاعَة.",
    "apply": "خُذِ النُّقْطَةَ (٤، ٢) المُمَثَّلَةَ بِالعَدَدِ المُرَكَّبِ (٤ + ٢ت)، وَاضْرِبْهَا جَبْرِيًّا فِي (ت) لِتَحْصُلَ عَلَى (-٢ + ٤ت)، ثُمَّ عَيِّنِ النُّقْطَتَيْنِ (٤، ٢) و(-٢، ٤) عَلَى وَرَقَةِ مُرَبَّعَاتٍ لِتَرَى بِعَيْنِكَ الزَّاوِيَةَ القَائِمَةَ ٩٠° بَيْنَهُمَا!",
