    "essence": "لَا يَفْهَمُ المُعَالِجُ الإِلِكْتُرُونِيُّ إِلَّا حَالَتَيْنِ فِيزْيَائِيَّتَيْنِ وَاضِحَتَيْنِ: مُرُورَ التَّيَّارِ (١) أَوِ انْقِطَاعَهُ (٠). وَفِي هٰذَا «النِّظَامِ الثُّنَائِيِّ» تَتَضَاعَفُ قِيمَةُ الخَانَاتِ مِنَ اليَمِينِ لِلْيَسَارِ بِقُوَى الِاثْنَيْنِ (١، ٢، ٤، ٨، ١٦، ٣٢، ٦٤، ١٢٨...)؛ فَالرَّقْمُ الثُّنَائِيُّ ١١٠١ يُسَاوِي ١ + ٠ + ٤ + ٨ = ١٣!\n\nيُكَوِّنُ كُلُّ ٨ بِتَّاتٍ مَعًا «بَايْتًا وَاحِدًا» يَتَّسِعُ ل ٢⁸ = ٢٥٦ قِيمَةً مُخْتَلِفَةً تَكْفِي لِتَمْثِيلِ حَرْفٍ أَوْ دَرَجَةِ لَوْنٍ. وَلِتَسْجِيلِ الصَّوْتِ الرَّقْمِيِّ النَّقِيِّ يُقَطَّعُ الصَّوْتُ ٤٤٬١٠٠ مَرَّةٍ فِي الثَّانِيَةِ وَيُسَجَّلُ كُلُّ قِيَاسٍ بِأَرْقَامٍ ثُنَائِيَّةٍ فَتُحْفَظُ التِّلَاوَاتُ وَالمَحَاضَرَاتُ بِلَا تَلَفٍ عَبْرَ السِّنِينَ.",
    "tutorContext": "تَحْوِيل ثنائيّ إِلَى عَشَرِيّ: نَضْرِب كُلّ خَانَة فِي 2^رُتْبَتُهَا بَدْءًا مِنْ 2^0 يَمِينًا. أَكْبَر عَدَد فِي 8 بِتَّاتٍ (11111111) هُوَ 2^8 - 1 = 255 (وَعَدَد الحَالَاتِ مِنْ 0 إِلَى 255 هُوَ 256 حَالَة). 1 كِيلُوبَايْت ثنائيّ (KiB) = 1024 بِاَيَتِ = 2^10.",
