      "stem": "لِمَاذَا تُخَزِّنُ المَنْصَّاتُ الآمِنَةُ بَصْمَةَ التَّجْزِئَةِ (Hash) لِكَلِمَةِ المُرُورِ بَدَلًا مِنْ حِفْظِ كَلِمَةِ المُرُورِ نَفْسِهَا كَنَصٍّ صَرِيحٍ؟",
