      "مُقَارَنَةُ إِنْفَاقِ مَبْلَغٍ مَرَّةً وَاحِدَةً بِاسْتِثْمَارِهِ وَقْفِيًّا يَخْدِمُ المَدَارِسَ وَالمَشَافِي مِئَاتِ السِّنِينَ"
