    "essence": "تَدْرُسُ «نَظَرِيَّةُ الأَلْعَابِ» القَرَارَاتِ الِاسْتِرَاتِيجِيَّةَ حِينَ تَعْتَمِدُ نَتِيجَةُ خِيَارِكَ عَلَى خِيَارِ الآخَرِينَ أَيْضًا. يَظُنُّ كَثِيرُونَ أَنَّ الحَيَاةَ كُلَّهَا «مُعَادَلَةٌ صِفْرِيَّةٌ» لَا يَرْبَحُ فِيهَا طَرَفٌ إِلَّا بِخَسَارَةِ الآخَرِ؛ بَيْنَمَا مُعْظَمُ العُمْرَانِ البَشَرِيِّ وَالتِّجَارَةِ وَالعِلْمِ «تَفَاعُلٌ غَيْرُ صِفْرِيٍّ» يَزْدَادُ فِيهِ الخَيْرُ الكُلِّيُّ بِالتَّعَاوُنِ وَيَتَلَاشَى بِالتَّنَازُعِ!\n\nتُظْهِرُ مَصْفُوفَاتُ العَوَائِدِ أَنَّ صَيَّادَيْنِ فِي بُحَيْرَةٍ إِذَا التَزَمَ كِلَاهُمَا بِالصَّيْدِ المُعْتَدِلِ نَالَ كُلٌّ مِنْهُمَا ١٠ سَمَكَاتٍ كُلَّ يَوْمٍ دَوَامًا (المَجْمُوعُ ٢٠)؛ أَمَّا إِذَا طَمِعَ كِلَاهُمَا فِي الصَّيْدِ الجَائِرِ اسْتَنْزَفَا البُحَيْرَةَ فَلَمْ يَجِدْ كُلُّ وَاحِدٍ إِلَّا ٣ سَمَكَاتٍ هَزِيلَةٍ (المَجْمُوعُ ٦)! فَالخُلُقُ الفَاضِلُ وَالعَهْدُ المُشْتَرَكُ هُمَا أَعْلَى صُوَرِ العَقْلَانِيَّةِ الرِّيَاضِيَّةِ البَعِيدَةِ المَدَى.",
    "tutorContext": "المُبَارَاَة الصِّفْرِيَّة مَجْمُوع عَوَائِد اللّاعبين فِيهَا = 0 (أَوْ مِقْدَارًا ثَابِتًا). مُعْضِلَة السَّجِينَيْن وَمَأْسَاة المَشَاعَاتِ (Tragedy of the Commons) تَوْضَحَانِ كَيْفَ يَقُود الجَشَع القَصِير النَّظَر إِلَى نَتِيجَةِ أَسْوَأ لِلجَمِيعِ مِنَ التَّعَاوُنِ العَادِلِ.",
    "apply": "كَوِّنْ جَدْوَلَ عَوَائِدَ صَغِيرًا (٢ × ٢) لِمَتْجَرَيْنِ مُتَجَاوِرَيْنِ يَخْتَارُ كُلٌّ مِنْهُمَا بَيْنَ «الأَمَانَةِ وَالجَوْدَةِ» و«الغِشِّ وَحَرْبِ الأَسْعَارِ» عَلَى مَدَى خَمْسِ سَنَوَاتٍ، وَقَارِنْ مَجْمُوعَ مَكْسَبِهِمَا عِنْدَ التَّعَاوُنِ النَّزِيهِ بمَجْمُوعِهِمَا عِنْدَ التَّضَارُبِ.",
