      "stem": "مَتَى تُسَمَّى العَلَاقَةُ الِاقْتِصَادِيَّةُ أَوِ الِاجْتِمَاعِيَّةُ فِي نَظَرِيَّةِ الأَلْعَابِ «لُعْبَةً غَيْرَ صِفْرِيَّةِ المَجْمُوعِ»؟",
